-- ============================================================================
-- DS_1: PostgreSQL Tourism Schema
-- Generated from Kaggle Hotel Booking Demand dataset
-- Source: https://github.com/rfordatascience/tidytuesday/tree/main/data/2020/2020-02-11
-- ============================================================================

-- Create schema
CREATE SCHEMA IF NOT EXISTS tourism;
SET search_path TO tourism, public;

-- ============================================================================
-- TABLE 1: HOTELS (20 European tourism hotels)
-- ============================================================================
DROP TABLE IF EXISTS tourism.bookings CASCADE;
DROP TABLE IF EXISTS tourism.tourists CASCADE;
DROP TABLE IF EXISTS tourism.hotels CASCADE;

CREATE TABLE tourism.hotels (
    hotel_id SERIAL PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    star_rating INTEGER CHECK (star_rating BETWEEN 1 AND 5),
    city VARCHAR(100) NOT NULL,
    country VARCHAR(100) NOT NULL,
    capacity INTEGER,
    price_per_night NUMERIC(10,2)
);

-- Insert hotel data

-- ============================================================================
-- TABLE 2: TOURISTS (38 tourist profiles from 38 countries)
-- ============================================================================
CREATE TABLE tourism.tourists (
    tourist_id SERIAL PRIMARY KEY,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    email VARCHAR(200),
    country VARCHAR(100),
    birth_date DATE,
    registration_date DATE DEFAULT CURRENT_DATE
);

-- Insert tourist data

-- ============================================================================
-- TABLE 3: BOOKINGS (500 bookings derived from Kaggle Hotel Booking Demand)
-- ============================================================================
CREATE TABLE tourism.bookings (
    booking_id SERIAL PRIMARY KEY,
    tourist_id INTEGER REFERENCES tourism.tourists(tourist_id),
    hotel_id INTEGER REFERENCES tourism.hotels(hotel_id),
    check_in_date DATE NOT NULL,
    check_out_date DATE NOT NULL,
    num_guests INTEGER DEFAULT 1,
    total_amount NUMERIC(12,2),
    booking_status VARCHAR(20) DEFAULT 'CONFIRMED',
    booking_date DATE DEFAULT CURRENT_DATE
);

-- Create indexes
CREATE INDEX idx_bookings_tourist ON tourism.bookings(tourist_id);
CREATE INDEX idx_bookings_hotel ON tourism.bookings(hotel_id);
CREATE INDEX idx_bookings_checkin ON tourism.bookings(check_in_date);
CREATE INDEX idx_bookings_status ON tourism.bookings(booking_status);
CREATE INDEX idx_hotels_city ON tourism.hotels(city);
CREATE INDEX idx_hotels_star ON tourism.hotels(star_rating);
CREATE INDEX idx_tourists_country ON tourism.tourists(country);

-- Insert booking data

-- Reset sequences
SELECT setval('tourism.hotels_hotel_id_seq', (SELECT MAX(hotel_id) FROM tourism.hotels));
SELECT setval('tourism.tourists_tourist_id_seq', (SELECT MAX(tourist_id) FROM tourism.tourists));
SELECT setval('tourism.bookings_booking_id_seq', (SELECT MAX(booking_id) FROM tourism.bookings));

-- Verification queries
SELECT 'Hotels' as entity, COUNT(*) as count FROM tourism.hotels
UNION ALL SELECT 'Tourists', COUNT(*) FROM tourism.tourists
UNION ALL SELECT 'Bookings', COUNT(*) FROM tourism.bookings;
